    justify-content: center;
    font-family: 'VT323', monospace;
    overflow: hidden;
    user-select: none;
  }
  .window {
    width: min(96vw, 1000px);
    background: #c0c0c0;
    border: 2px solid;
    border-color: #fff #000 #000 #fff;
