    display: flex;
    flex-direction: column;
  }
  .titlebar {
    background: linear-gradient(#1084d8, #000080);
    color: #fff;
    font-family: 'Press Start 2P', monospace;
    font-size: 10px;
    padding: 5px 8px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    user-select: none;
  }
  .titlebar .title { letter-spacing: 1px; }
  .titlebar .buttons { display: flex; gap: 4px; }
  .titlebar .buttons button {
    width: 18px; height: 16px;
    background: #c0c0c0;
    border: 1px solid;
    border-color: #fff #000 #000 #fff;
    font-size: 9px;
    line-height: 1;
    cursor: pointer;
    font-family: monospace;
    padding: 0;
    color: #000;
  }
  .titlebar .buttons button:hover { background: #d8d8d8; }
  .menubar {
    background: #c0c0c0;
    border-bottom: 1px solid #000;
    padding: 2px 6px;
    font-size: 16px;
    color: #000;
    display: flex;
    gap: 16px;
  }
  .menubar span { cursor: pointer; }
  .menubar span:hover { background: #1084d8; color: #fff; }
  .body { position: relative; flex: 1; background: #000; }
  canvas { display: block; width: 100%; height: auto; cursor: crosshair; }
  .statusbar {
    background: #c0c0c0;
    border-top: 1px solid #fff;
    padding: 3px 8px;
    font-size: 15px;
    color: #000;
  }
</style>
